// Vite build for the Preact SPA (ADR 0004 §4.3). `vite build` emits web/dist,
// which worker/wrangler.jsonc serves as Static Assets. web/public (generated by
// scripts/gen-config.ts: oauth/client-metadata.json, _headers) is copied as is.
//
// Dev: the SPA runs on 127.0.0.1 (an atproto loopback OAuth client must use
// 127.0.0.1, not localhost) and proxies the Worker routes to `wrangler dev`.

import preact from '@preact/preset-vite';
import { defineConfig } from 'vite';

const WORKER_DEV = 'http://127.0.0.1:8787';

export default defineConfig({
  plugins: [preact()],
  server: {
    host: '127.0.0.1',
    port: 5173,
    strictPort: true,
    proxy: {
      '/api': { target: WORKER_DEV },
      '/health': { target: WORKER_DEV },
    },
  },
  preview: {
    host: '127.0.0.1',
    port: 4173,
    strictPort: true,
  },
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
    emptyOutDir: true,
    // The CSP has no 'unsafe-inline' and requires Trusted Types: keep every
    // asset a file and skip the inline module-preload polyfill.
    assetsInlineLimit: 0,
    modulePreload: { polyfill: false },
    sourcemap: false,
  },
});
